// The phone's Terminal screen runs xterm.js inside a WebView, which loads one HTML string: no bundler serves it files.
// This copies xterm's script, its fit addon and its stylesheet into apps/mobile/src/xterm-bundle.gen.ts. Run it again
// after updating @xterm/xterm or @xterm/addon-fit (desktop's dependencies, which the phone's copy follows).
const fs = require("node:fs");
const path = require("node:path");

const root = path.resolve(__dirname, "..");
const read = (file) => fs.readFileSync(require.resolve(file, { paths: [path.join(root, "apps/desktop")] }), "utf8");
const version = (name) => JSON.parse(read(`${name}/package.json`)).version;
// Inside a <script>, only "</script" could end the element early.
const inline = (text) => JSON.stringify(text.replace(/<\/script/gi, "<\\/script"));

function generateXtermBundle(target = path.join(root, "apps/mobile/src/xterm-bundle.gen.ts")) {
  const source = [
    `// Generated by scripts/generate-xterm-bundle.cjs from @xterm/xterm ${version("@xterm/xterm")} and @xterm/addon-fit ${version("@xterm/addon-fit")}. Do not edit.`,
    `export const XTERM_JS = ${inline(read("@xterm/xterm/lib/xterm.js").replace(/\n\/\/# sourceMappingURL=.*$/, ""))};`,
    `export const XTERM_FIT_JS = ${inline(read("@xterm/addon-fit/lib/addon-fit.js").replace(/\n\/\/# sourceMappingURL=.*$/, ""))};`,
    `export const XTERM_CSS = ${JSON.stringify(read("@xterm/xterm/css/xterm.css"))};`,
    "",
  ].join("\n");
  fs.writeFileSync(target, source);
  return target;
}

module.exports = { generateXtermBundle };
if (require.main === module) console.log(path.relative(root, generateXtermBundle()));
